INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (1, 1, 'Mən / Sən', 'I / You', 'Mən = I, Sən = You', 'I = Mən, You = Sən', 'I am Mahammad. You are Zohrab.', 'Mən Mahammadam. Sən Zohrabsan.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (2, 1, 'Mənəm / Sənsən', 'I am / You are', 'Mən …am/əm = I am, Sən …san/sən = You are', 'I am, You are', 'I am Mahammad. You are Zohrab.', 'Mən Mahammadam. Sən Zohrabsan.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (3, 1, 'Qısa formalar', 'I''m / You''re', 'I am → I''m, You are → You''re', 'Short forms of I am / You are', 'I''m Mahammad. You''re Zohrab.', 'Mən Mahammadam. Sən Zohrabsan.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (4, 1, 'Bəli / Xeyr cavabları', 'Yes, I am / No, I''m not', 'Bəli, mənəm = Yes, I am. Xeyr, mən deyiləm = No, I''m not.', 'Positive and negative short answers', 'Are you Zohrab? Yes, I am. / No, I''m not.', 'Sən Zohrabsan? Bəli, mənəm. / Xeyr, mən deyiləm.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (5, 1, 'Suallar', 'Are you…? / What''s your name?', 'Sən …san? = Are you…? Adın nədir? = What''s your name?', 'Questions with be and asking names', 'Are you Mahammad? What''s your name?', 'Sən Mahammadsan? Adın nədir?');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (6, 2, 'O (kişi), O (qadın), O (əşya/yer)', 'He (man), She (woman), It (thing/place)', 'Kişilər, qadınlar və əşyalar üçün işlənir.', 'Used for men, women, things and places.', 'He is from Spain. She is from Brazil. It’s Tuesday.', 'O İspaniyadandır. O Braziliyadandır. Çərşənbə axşamı günüdür.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (7, 2, 'Odur (kişi), Odur (qadın), Odur (əşya/yer)', 'He is, She is, It is', 'İnsan və ya əşya haqqında məlumat vermək üçün işlənir.', 'Used to give information about a person or thing.', 'He is from China. She is from the United States. It is Saturday.', 'O Çindəndir. O ABŞ-dandır. Şənbə günüdür.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (8, 2, 'Qısa formalar (kişi, qadın, əşya/yer)', 'Short forms for people and things', 'Danışıqda daha çox işlənən qısa formalardır.', 'Common short forms used in everyday English.', 'He’s from Azerbaijan. She’s from Spain. It’s Sunday.', 'O Azərbaycandandır. O İspaniyadandır. Bazar günüdür.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (9, 2, 'O deyil (kişi, qadın, əşya/yer)', 'Negative forms for people and things', '“Deyil” demək üçün işlənir.', 'Used to say something is not true.', 'He isn’t from Russia. She isn’t from China. It isn’t Friday.', 'O Rusiyadan deyil. O Çindən deyil. Cümə günü deyil.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (10, 2, 'O haradandır? (kişi və qadın)', 'Asking where someone is from', 'Birinin haralı olduğunu soruşmaq üçün işlənir.', 'Used to ask where someone is from.', 'Where’s he from? Where’s she from?', 'O haradandır? O haradandır?');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (11, 3, 'Biz, siz, onlar', 'We, You, They', 'We = biz, You = siz, They = onlar. Bir neçə nəfərdən danışarkən işlənir.', 'We = biz, You = siz, They = onlar. Used for groups of people.', 'We are Azerbaijani.', 'Biz Azərbaycanlıyıq.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (12, 3, 'Bizik, sizsiniz, onlardır', 'We are, You are, They are', 'We are = bizik, You are = sizsiniz, They are = onlardır. Bir qrup haqqında məlumat vermək üçün işlənir.', 'Used to give information about groups.', 'They are American.', 'Onlar amerikalıdırlar.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (13, 3, 'Qısa formalar', 'We’re, You’re, They’re', 'We’re = We are, You’re = You are, They’re = They are. Danışıqda istifadə olunur.', 'Common short forms used in speech.', 'We’re Azerbaijani.', 'Biz Azərbaycanlıyıq');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (14, 3, 'İnkar formaları', 'We aren’t, You aren’t, They aren’t', 'We aren’t = biz deyilik, You aren’t = siz deyilsiniz, They aren’t = onlar deyillər.', 'Used to say something is not true.', 'We aren’t English.', 'Biz ingilis deyilik.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (15, 3, 'Sual formaları', 'Are you…? / Are they…?', 'Are you…? = Siz …siniz? Are they…? = Onlar …dır? Sual vermək üçün işlənir.', 'Used to ask questions about people.', 'Are they Turkish?', 'Onlar türkdürlər?');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (16, 4, 'Ad və soyad soruşmaq', 'Asking first name and surname', 'Bir şəxsin adını və soyadını soruşmaq üçün What is your first name? və What is your surname? işlədilir.', 'Use What is your first name? and What is your surname? to ask a person''s first name and surname.', 'What is your first name? What is your surname?', 'Adın nədir? Soyadın nədir?');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (17, 4, 'Telefon nömrəsini soruşmaq', 'Asking for a phone number', 'Bir şəxsin telefon nömrəsini soruşmaq üçün What is your phone number? işlədilir.', 'Use What is your phone number? to ask for someone''s phone number.', 'What is your phone number? My phone number is 0771234567.', 'Telefon nömrən nədir? Mənim telefon nömrəm 0771234567-dir.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (18, 4, 'Haradan olduğunu soruşmaq', 'Asking where someone is from', 'Birinin hansı ölkədən olduğunu soruşmaq üçün Where are you from? işlədilir.', 'Use Where are you from? to ask where someone is from.', 'Where are you from? I am from Azerbaijan.', 'Haradansan? Mən Azərbaycandanam.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (19, 4, 'Kim olduğunu soruşmaq', 'Asking who someone is', 'Bir şəxsin kim olduğunu soruşmaq üçün Who is he? və Who is she? işlədilir.', 'Use Who is he? and Who is she? to ask who a person is.', 'Who is Mehriban? She is Mahammad''s friend.', 'Mehriban kimdir? O, Mahammadın dostudur.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (20, 4, 'Yaşı soruşmaq', 'Asking age', 'Birinin yaşını soruşmaq üçün How old are you? işlədilir.', 'Use How old are you? to ask someone''s age.', 'How old are you? I am 22 years old.', 'Neçə yaşın var? Mənim 22 yaşım var.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (21, 5, 'Tək isimlər', 'Singular nouns', 'Bir əşya və ya bir insan haqqında danışanda isim tək formada olur.', 'Use singular nouns to talk about one person or one thing.', 'It is a book. It is a phone.', 'Bu kitabdır. Bu telefondur.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (22, 5, 'Cəm isimlər', 'Plural nouns', 'İki və ya daha çox əşya haqqında danışanda isim cəm formada işlənir. Çox vaxt sözün sonuna -s əlavə olunur.', 'Use plural nouns to talk about two or more things. Usually add -s.', 'They are books. They are phones.', 'Bunlar kitablardır. Bunlar telefonlardır.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (23, 5, 'a artiklı', 'Indefinite article a', 'Samit səslə başlayan tək sayılan isimlərdən əvvəl a işlədilir.', 'Use a before singular countable nouns beginning with a consonant sound.', 'a book a pencil a phone', 'bir kitab bir karandaş bir telefon');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (24, 5, 'an artiklı', 'Indefinite article an', 'Sait səslə başlayan tək sayılan isimlərdən əvvəl an işlədilir.', 'Use an before singular countable nouns beginning with a vowel sound.', 'an umbrella an ID card', 'bir çətir bir şəxsiyyət vəsiqəsi');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (25, 6, 'Bu (yaxında, tək)', 'This', 'Yaxında olan tək əşyanı göstərmək üçün this işlədilir.', 'Use this to talk about one thing that is near you.', 'This is a mug.', 'Bu fincandır.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (26, 6, 'O (uzaqda, tək)', 'That', 'Uzaqda olan tək əşyanı göstərmək üçün that işlədilir.', 'Use that to talk about one thing that is far from you.', 'That is a map.', 'O xəritədir.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (27, 6, 'Bunlar (yaxında, cəm)', 'These', 'Yaxında olan bir neçə əşyanı göstərmək üçün these işlədilir.', 'Use these to talk about things that are near you.', 'These are postcards.', 'Bunlar açıqcalardır.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (28, 6, 'Onlar (uzaqda, cəm)', 'Those', 'Uzaqda olan bir neçə əşyanı göstərmək üçün those işlədilir.', 'Use those to talk about things that are far from you.', 'Those are key rings.', 'Onlar açar breloklarıdır.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (29, 8, 'Mənsubiyyət əvəzlikləri (1)', 'Possessive Adjectives (1)', 'my = mənim your = sənin / sizin Bu sözlər sahiblik bildirir və isimdən əvvəl işlənir.', 'my and your show possession. They come before a noun.', 'This is my brother. Is this your bag?', 'Bu mənim qardaşımdır. Bu sənin çantandır?');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (30, 8, 'Mənsubiyyət əvəzlikləri (2)', 'Possessive Adjectives (2)', 'his = onun (kişi) her = onun (qadın) its = onun (heyvan / əşya)', 'his, her and its show possession. They come before a noun.', 'His name is Ayxan. Her name is Mehriban. Its colour is black.', 'Onun adı Ayxandır. Onun adı Mehribandır. Onun rəngi qaradır.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (31, 8, 'Mənsubiyyət əvəzlikləri (3)', 'Possessive Adjectives (3)', 'our = bizim their = onların Bu sözlər sahiblik bildirir və isimdən əvvəl işlənir.', 'our and their show possession. They come before a noun.', 'This is our house. These are their children.', 'Bu bizim evimizdir. Bunlar onların uşaqlarıdır.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (32, 8, 'Apostrof ''s', 'Possessive ''s', 'Bir insana aid olan şeyi göstərmək üçün adın sonuna ''s əlavə olunur.', 'Add ''s to a person''s name to show possession.', 'Mahammad''s sister Mehriban''s brother', 'Mahammadın bacısı Mehribanın qardaşı');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (33, 9, 'Sifət isimdən əvvəl gəlir', 'Adjective before noun', 'İngiliscədə sifət çox vaxt isimdən əvvəl işlənir.', 'In English, an adjective usually comes before a noun.', 'It is a fast car.', 'Bu sürətli maşındır.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (34, 9, 'Sifət be feilindən sonra gəlir', 'Adjective after be', 'Sifət am / is / are-dan sonra da işlənə bilər.', 'An adjective can also come after am / is / are.', 'The car is fast.', 'Maşın sürətlidir.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (35, 9, 'Sifətin cəm forması yoxdur', 'Adjectives do not change in plural', 'Sifət cəm olanda -s qəbul etmir. good cars düzgündür, goods cars səhvdir.', 'Adjectives do not take -s in plural. good cars is correct, goods cars is wrong.', 'They are good cars.', 'Onlar yaxşı maşınlardır.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (36, 9, 'Very + sifət', 'Very + adjective', 'Very sifəti gücləndirir və sifətdən əvvəl gəlir.', 'Very makes an adjective stronger and comes before the adjective.', 'It is very fast.', 'O çox sürətlidir.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (37, 11, 'Present Simple müsbət forma', 'Present Simple positive', 'I / you / we / they ilə felin əsas forması işlənir.', 'Use the base verb with I / you / we / they.', 'We have breakfast at home.', 'Biz evdə səhər yeməyi yeyirik.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (38, 11, 'Present Simple inkar forma', 'Present Simple negative', 'I / you / we / they ilə inkar üçün don''t + əsas fel işlənir.', 'Use don''t + base verb for negatives with I / you / we / they.', 'I don''t drink coffee.', 'Mən qəhvə içmirəm.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (39, 11, 'Have, eat, drink', 'Have, eat, drink', 'Yemək və içki haqqında danışanda have, eat və drink işlənir.', 'Use have, eat and drink to talk about food and drink.', 'I have cereal and I drink tea.', 'Mən taxıl lopası yeyirəm və çay içirəm.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (40, 11, 'Like / prefer', 'Like / prefer', 'Like və prefer sevdiyimiz şeyləri demək üçün işlənir.', 'Use like and prefer to talk about things you like.', 'I like my breakfast.', 'Mən səhər yeməyimi bəyənirəm.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (41, 12, 'Do you...?', 'Do you...?', 'I / you / we / they ilə sual yaratmaq üçün cümlənin əvvəlinə Do gəlir.', 'Use Do at the beginning to make questions with I / you / we / they.', 'Do you live in Baku?', 'Sən Bakıda yaşayırsan?');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (42, 12, 'Qısa cavablar', 'Short answers', 'Do sualına qısa cavab: Yes, I do. / No, I don''t.', 'Short answers to Do questions are Yes, I do. / No, I don''t.', 'Do you have children? Yes, I do.', 'Uşaqların var? Bəli, var.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (43, 12, 'Do we / Do they', 'Do we / Do they', 'We və they ilə də sualda Do işlənir.', 'Use Do in questions with we and they too.', 'Do they drink coffee?', 'Onlar qəhvə içirlər?');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (44, 12, 'Sual sözü + do you', 'Question word + do you', 'Where, What kimi sual sözləri Do you-dan əvvəl gəlir.', 'Question words like Where and What come before do you.', 'Where do you live?', 'Sən harada yaşayırsan?');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (45, 14, 'He / She / It ilə müsbət forma', 'Present Simple: he / she / it positive', 'He / she / it ilə felə çox vaxt -s əlavə olunur.', 'With he / she / it, add -s to the verb in positive sentences.', 'She works in a hospital.', 'O xəstəxanada işləyir.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (46, 14, '-es əlavə olunan fellər', 'Verbs with -es', 'do, go, watch kimi fellərdə he / she / it ilə -es işlənir.', 'Use -es with verbs like do, go and watch after he / she / it.', 'He watches TV.', 'O televizora baxır.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (47, 14, 'Doesn''t + əsas fel', 'Doesn''t + base verb', 'He / she / it ilə inkar cümləsində doesn''t + felin əsas forması işlənir.', 'Use doesn''t + base verb in negative sentences with he / she / it.', 'She doesn''t work in a bank.', 'O bankda işləmir.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (48, 14, 'Does ilə sual', 'Questions with does', 'He / she / it ilə sual üçün cümlənin əvvəlinə Does gəlir. Feldə -s olmur.', 'Use Does at the beginning for questions with he / she / it. The main verb has no -s.', 'Does he work in Baku?', 'O Bakıda işləyir?');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (49, 14, 'What / Where does...?', 'Question word + does', 'What və Where kimi sual sözləri Does-dan əvvəl gəlir.', 'Question words like What and Where come before does.', 'Where does she work?', 'O harada işləyir?');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (50, 15, 'Tezlik zərfləri', 'Adverbs of frequency', 'always, usually, often, sometimes, never hərəkətin nə qədər tez-tez olduğunu göstərir.', 'Always, usually, often, sometimes and never show how often something happens.', 'I usually get up at seven.', 'Mən adətən saat yeddidə qalxıram.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (51, 15, 'Zərfin yeri', 'Position of adverbs', 'Tezlik zərfləri əsas feldən əvvəl gəlir.', 'Adverbs of frequency usually come before the main verb.', 'I always have breakfast at home.', 'Mən həmişə evdə səhər yeməyi yeyirəm.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (52, 15, 'Never mənfi məna verir', 'Never', 'Never özü mənfi məna verir, ona görə don''t ilə birlikdə işlətməyirik.', 'Never is already negative, so don''t use it with don''t.', 'I never drink coffee.', 'Mən heç vaxt qəhvə içmirəm.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (53, 15, 'Vaxt sözləri', 'Time words', 'then, after, before, until və about günlük rutin danışanda çox işlənir.', 'Then, after, before, until and about are useful for daily routines.', 'After work, I go home.', 'İşdən sonra evə gedirəm.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (54, 17, 'Be ilə sual sırası', 'Question order with be', 'Be ilə sualda am / is / are subyektdən əvvəl gəlir.', 'In questions with be, am / is / are come before the subject.', 'Where is Nigar from?', 'Nigar haradandır?');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (55, 17, 'Present Simple sual sırası', 'Present Simple question order', 'Present Simple sualında sıra: sual sözü + do/does + şəxs + fel.', 'The order is: question word + do/does + subject + verb.', 'What do you do in your free time?', 'Boş vaxtında nə edirsən?');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (56, 17, 'How often sualı', 'How often questions', 'How often bir hərəkətin nə qədər tez-tez olduğunu soruşur.', 'How often asks about frequency.', 'How often do you train?', 'Nə qədər tez-tez məşq edirsən?');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (57, 17, 'What time sualı', 'What time questions', 'What time saatı soruşmaq üçün işlənir.', 'Use What time to ask about time.', 'What time do you usually get up?', 'Adətən saat neçədə qalxırsan?');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (58, 18, 'Əmr cümlələri', 'Imperatives', 'Əmr cümləsində felin əsas forması ilə başlayırıq.', 'Imperatives start with the base verb.', 'Sit down.', 'Otur.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (59, 18, 'İnkar əmr cümləsi', 'Negative imperatives', 'İnkar əmr cümləsi üçün Don''t + fel işlənir.', 'Use Don''t + base verb for negative imperatives.', 'Don''t move.', 'Tərpənmə.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (60, 18, 'Object pronouns', 'Object pronouns', 'me, you, him, her, it, us, them obyekt əvəzlikləridir.', 'Me, you, him, her, it, us and them are object pronouns.', 'I love her.', 'Mən onu sevirəm.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (61, 18, 'Feldən sonra obyekt əvəzliyi', 'Object pronoun after verbs', 'Obyekt əvəzliyi çox vaxt feldən sonra gəlir.', 'Object pronouns usually come after verbs.', 'Listen to me.', 'Mənə qulaq as.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (62, 20, 'Can müsbət forma', 'Can affirmative', 'Can bacarıq və ya imkan bildirmək üçün işlənir. Ondan sonra felin əsas forması gəlir.', 'Use can to talk about ability or possibility. The base verb comes after can.', 'I can drive.', 'Mən maşın sürə bilirəm.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (63, 20, 'Can’t inkar forma', 'Can’t negative', 'Can’t bacarıqsızlıq və ya qadağa bildirir.', 'Use can’t for inability or prohibition.', 'You can’t park here.', 'Sən burada park edə bilməzsən.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (64, 20, 'Can ilə sual', 'Questions with can', 'Can ilə sual qurarkən can cümlənin əvvəlində gəlir.', 'Put can at the beginning to make a question.', 'Can you come on Monday?', 'Bazar ertəsi gələ bilərsən?');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (65, 20, 'Qısa cavablar', 'Short answers', 'Can sualına Yes, I can / No, I can’t kimi qısa cavab verilir.', 'Use short answers like Yes, I can / No, I can’t.', 'Yes, I can.', 'Bəli, bacarıram.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (66, 21, 'Like + fel + ing', 'Like + verb + -ing', 'Like sözündən sonra felə -ing artırılır.', 'After like, use a verb with -ing.', 'I like reading.', 'Mən oxumağı sevirəm.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (67, 21, 'Love + fel + ing', 'Love + verb + -ing', 'Love sözündən sonra da felin -ing forması gəlir.', 'After love, use the -ing form of the verb.', 'Leyla loves swimming.', 'Leyla üzməyi çox sevir.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (68, 21, 'Hate + fel + ing', 'Hate + verb + -ing', 'Hate ilə də felin -ing forması işlənir.', 'After hate, use a verb with -ing.', 'Mahammad hates flying.', 'Mahammad təyyarə ilə getməyə nifrət edir.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (69, 21, 'Sual: What do you like doing?', 'Question: What do you like doing?', 'Bir insanın xoşladığı fəaliyyətləri soruşmaq üçün işlənir.', 'Use it to ask about activities someone likes.', 'What do you like doing?', 'Nə etməyi xoşlayırsan?');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (70, 23, 'Can / can’t təkrar', 'Can / can’t review', 'Can bacarıq və imkan, can’t isə mümkünsüzlük və ya qadağa bildirir.', 'Can shows ability or possibility, and can’t shows inability or prohibition.', 'You can visit the museum.', 'Sən muzeyi ziyarət edə bilərsən.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (71, 23, 'Like / love / hate + -ing təkrar', 'Like / love / hate + -ing review', 'Bu fellərdən sonra fəaliyyət bildirən fel -ing ilə işlənir.', 'Use the -ing form after like, love and hate.', 'I love walking in the park.', 'Mən parkda gəzməyi çox sevirəm.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (72, 24, 'Present continuous', 'Present continuous', 'İndiki anda baş verən hərəkəti am/is/are + verb-ing ilə deyirik.', 'Use am/is/are + verb-ing for actions happening now.', 'I am waiting outside.', 'Mən çöldə gözləyirəm.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (73, 24, 'What are you doing?', 'What are you doing?', 'Hazırda nə etdiyini soruşmaq üçün bu sualdan istifadə olunur.', 'Use this question to ask about an action happening now.', 'What are you doing?', 'Nə edirsən?');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (74, 24, 'Present continuous qısa cavab', 'Present continuous short answers', 'Müsbət və mənfi cavabda am/is/are formasından istifadə olunur.', 'Use am/is/are in short present continuous answers.', 'She is checking in.', 'O, qeydiyyatdan keçir.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (75, 24, 'Present simple və present continuous fərqi', 'Present simple vs present continuous', 'Present simple adətləri, present continuous isə indi olan hərəkəti bildirir.', 'Present simple describes routines; present continuous describes actions happening now.', 'I drive every day, but now I’m waiting.', 'Mən hər gün maşın sürürəm, amma indi gözləyirəm.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (76, 25, 'Present Simple — hər gün', 'Present simple: every day', 'Hər gün, adətən təkrarlanan işlər üçün Present Simple işlədilir. Açar sözlər: usually, every day, always.', 'Use present simple for repeated actions.', 'Mahammad usually works in an office.', 'Mahammad adətən ofisdə işləyir.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (77, 25, 'Present Continuous — indi', 'Present continuous: now', 'İndi, bu gün baş verən iş üçün am/is/are + fel-ing işlədilir. Açar sözlər: now, today, at the moment.', 'Use present continuous for actions happening now.', 'Today he is working in a restaurant.', 'Bu gün o, restoranda işləyir.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (78, 25, 'İkisinin fərqi', 'Present simple or continuous?', 'Bir cümlədə ikisi qarşılaşdırıla bilər: adətən olan iş — Present Simple, bu gün olan iş — Present Continuous.', 'Compare the usual action and today’s action.', 'He usually wears a suit, but today he is wearing jeans.', 'O adətən kostyum geyinir, amma bu gün cins şalvar geyinib.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (79, 25, 'Sual fərqi', 'What do you do? / What are you doing?', 'What do you do? = Peşən nədir? What are you doing? = İndi nə edirsən? Cavab formaları da fərqlidir.', 'Two different questions with different meanings.', 'What do you do? I’m a teacher. What are you doing? I’m reading.', 'Peşən nədir? Müəlliməm. İndi nə edirsən? Oxuyuram.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (80, 26, 'Would you like + isim', 'Would you like + noun', 'Nəyisə təklif edərkən Would you like + isim işlədilir. Bu, Do you want-dan daha nəzakətlidir.', 'Offer something politely.', 'Would you like a coffee?', 'Qəhvə istəyirsən?');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (81, 26, 'Would you like to + fel', 'Would you like to + verb', 'Kimisə bir işə dəvət edərkən Would you like to + felin əsas forması işlədilir.', 'Invite somebody to do something.', 'Would you like to come to the match?', 'Oyuna gəlmək istəyirsən?');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (82, 26, 'I’d like', 'I’d like = I would like', 'I’d like = I would like. Nəzakətli istək bildirir. I want-dan daha yumşaqdır.', 'Polite way to say what you want.', 'I’d like a tea, please.', 'Zəhmət olmasa, bir çay istəyirəm.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (83, 26, 'Cavablar', 'Answers to invitations', 'Müsbət: Yes, I’d love to. Mənfi: Sorry, I can’t. Təklifə cavab: Yes, please. / No, thanks.', 'Accepting and refusing invitations.', 'Would you like to come? Yes, I’d love to.', 'Gəlmək istəyirsən? Bəli, çox məmnuniyyətlə.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (84, 27, 'There is a', 'There is a + singular', 'Bir şeyin mövcudluğunu bildirmək üçün There is a + tək isim işlədilir.', 'Say that one thing exists.', 'There is a lamp in the room.', 'Otaqda lampa var.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (85, 27, 'There are some', 'There are some + plural', 'Bir neçə şey üçün There are some + cəm isim işlədilir.', 'Say that several things exist.', 'There are some towels in the bathroom.', 'Hamamda dəsmallar var.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (86, 27, 'Mənfi forma', 'There isn’t / There aren’t any', 'Mənfidə: There isn’t a (tək), There aren’t any (cəm). Cəmdə some əvəzinə any işlənir.', 'Negative forms with any.', 'There isn’t a lift. There aren’t any shops.', 'Lift yoxdur. Mağaza yoxdur.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (87, 27, 'Sual forması', 'Is there…? / Are there any…?', 'Sualda: Is there a…? / Are there any…? Qısa cavab: Yes, there is. / No, there isn’t.', 'Questions and short answers.', 'Is there a swimming pool? Yes, there is.', 'Hovuz var? Bəli, var.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (88, 27, 'in / on / under', 'in, on, under', 'in = içində, on = üstündə, under = altında. Əşyanın yerini bildirir.', 'Prepositions of place.', 'The key is under the bed.', 'Açar çarpayının altındadır.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (89, 28, 'was / were', 'Past simple: was / were', 'be felinin keçmiş forması: I/he/she/it → was, you/we/they → were.', 'Past forms of the verb be.', 'I was at work. They were at home.', 'Mən işdə idim. Onlar evdə idilər.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (90, 28, 'Mənfi forma', 'wasn’t / weren’t', 'Mənfidə: wasn’t (was not), weren’t (were not).', 'Negative past forms of be.', 'She wasn’t at school yesterday.', 'O dünən məktəbdə deyildi.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (91, 28, 'Sual və qısa cavab', 'Was…? / Were…?', 'Sualda was/were əvvələ keçir. Qısa cavab: Yes, I was. / No, I wasn’t.', 'Questions and short answers with was/were.', 'Were you at the party? Yes, I was.', 'Məclisdə idin? Bəli, idim.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (92, 28, 'in / at / on — yerlər', 'in, at, on with places', 'at → home, work, school. in → the kitchen, the park, Baku. on → a bus, a train, a plane.', 'Prepositions with places.', 'I was on a bus at seven o’clock.', 'Saat yeddidə avtobusda idim.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (93, 30, 'Müntəzəm fellər: -ed', 'Past simple: regular verbs', 'Müntəzəm fellər keçmişdə -ed alır. Bütün şəxslər üçün eyni forma işlənir.', 'Regular verbs add -ed in the past.', 'I booked my ticket online.', 'Biletimi internetdən aldım.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (94, 30, 'Yazılış qaydaları', 'Spelling rules', '-e ilə bitirsə yalnız -d (arrive → arrived). Samit + y → -ied (study → studied). Qısa sözlərdə son samit ikiləşir (travel → travelled).', 'Spelling changes when adding -ed.', 'She studied in Ganja and travelled by bus.', 'O, Gəncədə oxudu və avtobusla getdi.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (95, 30, 'Mənfi forma', 'didn’t + verb', 'Mənfidə didn’t + felin əsas forması işlənir. Fel -ed ALMIR.', 'Negative: didn’t plus base verb.', 'I didn’t like the weather.', 'Hava mənim xoşuma gəlmədi.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (96, 30, 'Sual forması', 'Did…?', 'Sualda Did + felin əsas forması. Qısa cavab: Yes, I did. / No, I didn’t.', 'Questions with did.', 'Did you book the ticket? Yes, I did.', 'Bileti aldın? Bəli, aldım.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (97, 31, 'do → did', 'Irregular verb: do', 'do felinin keçmiş forması did-dir. Qaydaya tabe deyil, əzbərlənməlidir.', 'The past of do is did.', 'I did my homework yesterday.', 'Dünən ev tapşırığımı etdim.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (98, 31, 'get → got', 'Irregular verb: get', 'get felinin keçmiş forması got-dur.', 'The past of get is got.', 'She got a bus to the museum.', 'O, muzeyə avtobusla getdi.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (99, 31, 'go → went', 'Irregular verb: go', 'go felinin keçmiş forması went-dir.', 'The past of go is went.', 'We went to the café at one o’clock.', 'Biz saat birdə kafeyə getdik.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (100, 31, 'have → had', 'Irregular verb: have', 'have felinin keçmiş forması had-dır. Mənfi və sualda fel dəyişmir: didn’t have, Did you have?', 'The past of have is had.', 'We had lunch in the café.', 'Biz kafedə nahar etdik.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (101, 33, 'Nizamsız fellər 1', 'More irregular verbs 1', 'buy → bought, say → said, send → sent, tell → told. Bu fellər -ed almır.', 'Four irregular verbs to remember.', 'I bought two coffees and told her my name.', 'İki qəhvə aldım və ona adımı dedim.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (102, 33, 'Nizamsız fellər 2', 'More irregular verbs 2', 'leave → left, see → saw, sit → sat, write → wrote.', 'Four more irregular verbs.', 'I saw her on the train and she sat next to me.', 'Onu qatarda gördüm və o mənim yanımda oturdu.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (103, 33, 'Qarışıq istifadə', 'Regular and irregular together', 'Bir cümlədə müntəzəm və nizamsız fellər birlikdə işlənə bilər.', 'Mixing regular and irregular verbs.', 'I bought a coffee and we talked about music.', 'Qəhvə aldım və biz musiqidən danışdıq.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (104, 33, 'Was/Were yoxsa Did?', 'Was/Were or Did?', 'Vəziyyət üçün Was/Were, hərəkət üçün Did işlənir. Was it expensive? / Did you buy it?', 'Choosing between was/were and did.', 'Was it expensive? Did you buy it?', 'Bahalı idi? Onu aldın?');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (105, 34, 'Gələcək plan', 'Present continuous for future', 'Present Continuous gələcək plan üçün də işlənir — qərar artıq verilibsə.', 'Present continuous can talk about future plans.', 'I’m going to Quba next weekend.', 'Gələn həftəsonu Qubaya gedirəm.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (106, 34, 'Zaman ifadələri ilə', 'With future time expressions', 'Gələcək zaman ifadələri ilə birlikdə işlənir: tonight, tomorrow, next weekend.', 'Used with future time expressions.', 'We’re leaving tomorrow morning.', 'Sabah səhər yola düşürük.');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (107, 34, 'Sual forması', 'Questions about plans', 'Planları soruşmaq üçün: What are you doing tomorrow? Where are you staying?', 'Asking about future plans.', 'What are you doing next weekend?', 'Gələn həftəsonu nə edirsən?');
INSERT INTO public.lesson_grammar (grammar_id, lesson_id, topic_az, topic_en, explanation_az, explanation_en, example_en, example_az) VALUES (108, 34, 'İndi yoxsa gələcək?', 'Now or future?', 'Eyni forma iki mənada işlənir. Vaxt sözü mənanı müəyyən edir: now → indi, tomorrow → plan.', 'The time word shows the meaning.', 'I’m eating now. I’m leaving on Friday.', 'İndi yemək yeyirəm. Cümə günü yola düşürəm.');
INSERT INTO public.lesson_vocabulary (lesson_id, category, word_en, word_az, level, chunk, chunk_izah) VALUES (1, 'Greeting', 'Hello', 'Salam', 'A1', 1, 'Tək qrup — bu mövzuda cəmi 7 söz var (7-dən az), ona görə bölünmür: 7 kart göstərilir, sonra oyunlar gəlir.');
